603	    workspace: &Entity<Workspace>,
604	    cx: &App,
605	) -> Vec<WorkspaceMenuWorktreeLabel> {
606	    let root_paths = workspace.read(cx).root_paths(cx);
607	    let show_folder_name = root_paths.len() > 1;
608	    let project = workspace.read(cx).project().clone();
609	    let repository_snapshots: Vec<_> = project
610	        .read(cx)
611	        .repositories(cx)
612	        .values()
613	        .map(|repo| repo.read(cx).snapshot())
614	        .collect();
615	
616	    root_paths
617	        .into_iter()
618	        .map(|root_path| {
619	            let root_path = root_path.as_ref();
620	            let folder_name = root_path
621	                .file_name()
622	                .map(|name| SharedString::from(name.to_string_lossy().to_string()))
623	                .unwrap_or_default();
624	            let repository_snapshot = repository_snapshots
625	                .iter()
626	                .find(|snapshot| snapshot.work_directory_abs_path.as_ref() == root_path);
627	
628	            if let Some(snapshot) = repository_snapshot {
629	                let worktree_name = if snapshot.is_linked_worktree() {
630	                    snapshot
631	                        .main_worktree_abs_path()
632	                        .and_then(|main_worktree_path| {
633	                            project::linked_worktree_short_name(main_worktree_path, root_path)
634	                        })
635	                        .unwrap_or_else(|| folder_name.clone())
636	                } else {
637	                    "main".into()
638	                };
639	
640	                if show_folder_name {
641	                    WorkspaceMenuWorktreeLabel {
642	                        icon: Some(IconName::GitWorktree),
643	                        primary_name: folder_name,
644	                        secondary_name: Some(worktree_name),
645	                    }
646	                } else {
647	                    WorkspaceMenuWorktreeLabel {
648	                        icon: Some(IconName::GitWorktree),
649	                        primary_name: worktree_name,
650	                        secondary_name: None,
651	                    }
652	                }
653	            } else {
654	                WorkspaceMenuWorktreeLabel {
655	                    icon: None,
656	                    primary_name: folder_name,
657	                    secondary_name: None,
658	                }
659	            }
660	        })
